package factory

import (
	"context"
	"reflect"
	"strings"
	"testing"

	"github.com/gitdek/invariant/internal/formalize"
	"github.com/gitdek/invariant/internal/github"
)

// A revise queued after a subset of the choices must reach the formalizer.
// In #417, F1 and F3 were decided and F2 was answered in prose, but choose
// kept waiting for an explicit F2 choice and never reached the revise.
func TestPartialChoices422ReviseUsesChosenForks(t *testing.T) {
	r, forks, original := partialChoices422Rig(t)
	f1 := r.gh.say(1, "gitdek", "/invariant choose F1 A")
	f3 := r.gh.say(1, "gitdek", "/invariant choose F3 B")
	const clarification = "For F2, retain the original message and retry it on the next send."
	revision := r.gh.say(1, "gitdek", clarification+"\n\n/invariant revise")
	// Let the scripted formalizer propose once the factory actually calls
	// it. Deciding whether the prose resolves F2 belongs to that formalizer.
	r.form.forks = nil
	r.poll()
	if len(r.form.requests) != 2 {
		t.Fatalf("a revise after F1 and F3 must draft without an F2 choice: got %d drafts, want 2", len(r.form.requests))
	}
	req := r.form.requests[1]
	want := []formalize.Answer{
		partialChoices422Answer(forks[0], "A", f1),
		partialChoices422Answer(forks[2], "B", f3),
	}
	partialChoices422Answers(t, req.Answers, want)
	if !reflect.DeepEqual(req.Previous, original.Marker.Proposal) {
		t.Errorf("revise lost the draft it revises: previous = %+v, want %+v", req.Previous, original.Marker.Proposal)
	}
	if !strings.Contains(req.Markdown(), clarification) {
		t.Error("the formalizer did not receive the writer's explanation of F2")
	}
	p := r.expect(1, KindProposal, LabelProposal)
	partialChoices422Answers(t, p.Marker.Answers, want)
	for _, id := range []int64{f1.ID, f3.ID, revision.ID} {
		if !partialChoices422Replied(p.Marker.ReplyTo, id) {
			t.Errorf("draft reply_to = %v; missing consumed command %d", p.Marker.ReplyTo, id)
		}
	}
	partialChoices422NoPending(t, r)
	posts := len(r.gh.posts(1))
	r.poll()
	if len(r.form.requests) != 2 || len(r.gh.posts(1)) != posts {
		t.Fatal("consumed choices or revise were processed again on the next poll")
	}
}

// An incomplete choice set gets one actionable answer. The chosen values
// must survive that answer, whichever command later resumes the work.
func TestPartialChoices422NamesMissingForkAndRetainsAnswers(t *testing.T) {
	for _, resume := range []string{"choose", "revise"} {
		t.Run(resume, func(t *testing.T) {
			r, forks, _ := partialChoices422Rig(t)
			f1 := r.gh.say(1, "gitdek", "/invariant choose F1 A")
			f3 := r.gh.say(1, "gitdek", "/invariant choose F3 B")
			before := len(r.gh.posts(1))
			r.poll()
			if got := len(r.gh.posts(1)); got != before+1 {
				t.Fatalf("partial choices need one actionable reply naming F2: got %d new replies", got-before)
			}
			note := r.gh.last(1)
			if !strings.Contains(note.Comment.Body, "/invariant choose F2") {
				t.Errorf("partial-choice reply must say how to answer the missing F2:\n%s", note.Comment.Body)
			}
			for _, answered := range []string{"F1", "F3"} {
				if strings.Contains(note.Comment.Body, "/invariant choose "+answered) {
					t.Errorf("partial-choice reply asks for the already chosen %s again:\n%s", answered, note.Comment.Body)
				}
			}
			if !sameSet(r.gh.labelsOf(1), []string{LabelAsking}) {
				t.Errorf("partial choices must still wait for a person: labels = %v", r.gh.labelsOf(1))
			}
			r.poll()
			r.poll()
			if len(r.gh.posts(1)) != before+1 || len(r.form.requests) != 1 {
				t.Fatal("unchanged partial choices must neither repeat the reply nor start a draft")
			}
			// A new watcher must reconstruct the accepted choices from the
			// issue, rather than relying on the previous watcher's memory.
			old := r.f
			r.f = &Factory{Repository: old.Repository, GitHub: r.gh, Repo: old.Repo,
				Formalizer: r.form, Builder: r.build, Base: old.Base, Projects: old.Projects,
				Work: old.Work, Check: old.Check, Log: t.Logf}
			r.poll()
			if len(r.gh.posts(1)) != before+1 || len(r.form.requests) != 1 {
				t.Fatal("a restarted watcher must not repeat the partial-choice reply or start a draft")
			}

			want := []formalize.Answer{
				partialChoices422Answer(forks[0], "A", f1),
				partialChoices422Answer(forks[2], "B", f3),
			}
			if resume == "choose" {
				f2 := r.gh.say(1, "gitdek", "/invariant choose F2 A")
				want = append(want, partialChoices422Answer(forks[1], "A", f2))
			} else {
				r.gh.say(1, "gitdek", "For F2, retain the original message for the next send.\n\n/invariant revise")
			}
			r.form.forks = nil
			r.poll()
			if len(r.form.requests) != 2 {
				t.Fatalf("%s after the partial-choice reply must draft once: got %d drafts", resume, len(r.form.requests))
			}
			partialChoices422Answers(t, r.form.requests[1].Answers, want)
			p := r.expect(1, KindProposal, LabelProposal)
			partialChoices422Answers(t, p.Marker.Answers, want)
			partialChoices422NoPending(t, r)
			posts := len(r.gh.posts(1))
			r.poll()
			if len(r.form.requests) != 2 || len(r.gh.posts(1)) != posts {
				t.Fatal("completing partial choices must consume their commands exactly once")
			}
		})
	}
}

func partialChoices422Rig(t *testing.T) (*rig, []formalize.Fork, Post) {
	t.Helper()
	r := newRig(t)
	forks := []formalize.Fork{
		{ID: "F1", Question: "What happens when the buffer is full?", Options: []formalize.Option{{ID: "A", Says: "Wait for room."}, {ID: "B", Says: "Return an error."}}},
		{ID: "F2", Question: "What happens when sending fails?", Options: []formalize.Option{{ID: "A", Says: "Retry the original message."}, {ID: "B", Says: "Discard the message."}}},
		{ID: "F3", Question: "Who chooses when to send?", Options: []formalize.Option{{ID: "A", Says: "The producer chooses."}, {ID: "B", Says: "The shipper chooses."}}},
	}
	r.form.forks = forks
	r.gh.open(1, "gitdek", "Add a bounded buffer", "A buffer for log messages.\n\n/invariant solve")
	r.poll()
	return r, forks, r.expect(1, KindForks, LabelAsking)
}

func partialChoices422Answer(fork formalize.Fork, option string, comment github.Comment) formalize.Answer {
	o, _ := fork.Option(option)
	return formalize.Answer{Fork: fork.ID, Question: fork.Question, Option: o.ID, Says: o.Says, By: comment.User.Login, Comment: comment.URL}
}

func partialChoices422Answers(t *testing.T, got, want []formalize.Answer) {
	t.Helper()
	if len(got) != len(want) {
		t.Fatalf("decided answers = %+v; want exactly %+v", got, want)
	}
	seen := map[string]formalize.Answer{}
	for _, a := range got {
		if _, duplicate := seen[a.Fork]; duplicate {
			t.Fatalf("fork %s was recorded twice: %+v", a.Fork, got)
		}
		seen[a.Fork] = a
	}
	for _, a := range want {
		if seen[a.Fork] != a {
			t.Errorf("answer for %s = %+v; want %+v, including the writer and original comment", a.Fork, seen[a.Fork], a)
		}
	}
}

func partialChoices422Replied(ids []int64, want int64) bool {
	for _, id := range ids {
		if id == want {
			return true
		}
	}
	return false
}

func partialChoices422NoPending(t *testing.T, r *rig) {
	t.Helper()
	thread, err := r.f.read(context.Background(), *r.gh.issues[1])
	if err != nil {
		t.Fatal(err)
	}
	if pending := thread.Pending(); len(pending) != 0 {
		t.Errorf("consumed choices or revise remain pending: %+v", pending)
	}
}

sources.internal/factory/project_directory_accep:
package factory

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/gitdek/invariant/internal/project"
)

// A statement hash does not include a project's directory. Ratifying the
// same statements after a revise must honor the new Project: line, while
// an unchanged destination still recovers the original branch.
func TestRatifyingTheSameStatementsHonorsTheProjectDirectory(t *testing.T) {
	for _, tc := range []struct {
		name, before, after string
		advanceNumbering    bool
	}{
		{"numbered to named", "", "factory/decision-followup", false},
		{"named to named", "examples/old-buffer", "factory/decision-followup", false},
		{"same named directory", "factory/decision-followup", "factory/decision-followup", false},
		{"same numbered directory after base advances", "", "", true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			r := newRig(t)
			r.form.forks = nil
			r.build.stop = true
			body := "A bounded buffer.\n\n/invariant solve"
			if tc.before != "" {
				body += "\n\nProject: " + tc.before
			}
			r.gh.open(1, "gitdek", "Add a bounded buffer", body)
			r.poll()
			first := r.expect(1, KindProposal, LabelProposal)
			hash := first.Marker.Proposal.Hash
			r.gh.say(1, "gitdek", "/invariant ratify "+hash)
			r.poll()
			stopped := r.expect(1, KindFailed, LabelHumanReview)
			if stopped.Marker.PR != 0 || stopped.Marker.Failure != FailStopped {
				t.Fatalf("fixture did not stop before opening a pull request: %+v", stopped.Marker)
			}
			oldBranch, oldDir := stopped.Marker.Branch, stopped.Marker.Project
			oldHead := git(t, r.origin, "rev-parse", oldBranch)
			wantDir := tc.after
			if wantDir == "" {
				wantDir = oldDir
			}
			if tc.advanceNumbering {
				// An unrelated project may merge while this issue waits.
				// Its number must not relocate this issue's allocated project.
				seed := t.TempDir()
				git(t, seed, "clone", "--quiet", "--branch", "main", r.origin, ".")
				added := filepath.Join(seed, "examples", "03-unrelated")
				if err := os.MkdirAll(added, 0o755); err != nil {
					t.Fatal(err)
				}
				if err := os.WriteFile(filepath.Join(added, "README.md"), []byte("Another project.\n"), 0o644); err != nil {
					t.Fatal(err)
				}
				git(t, seed, "add", "examples/03-unrelated/README.md")
				git(t, seed, "-c", "user.name=Seed", "-c", "user.email=seed@example.com", "commit", "--quiet", "-m", "Add an unrelated project")
				git(t, seed, "push", "--quiet", "origin", "main")
			}

			r.gh.issues[1].Body = "A bounded buffer.\n\n/invariant solve"
			if tc.after != "" {
				r.gh.issues[1].Body += "\n\nProject: " + tc.after
			}
			r.gh.say(1, "gitdek", "Keep the statements; use the project's current directory.\n\n/invariant revise")
			r.poll()
			revised := r.expect(1, KindProposal, LabelProposal)
			if p := revised.Marker.Proposal; p.Hash != hash || p.Dir != tc.after {
				t.Fatalf("revision must change only the destination: hash %q, directory %q", p.Hash, p.Dir)
			}
			r.build.stop = false
			ratify := r.gh.say(1, "gitdek", "/invariant ratify "+hash)
			r.poll()
			built := r.expect(1, KindPR, LabelPR)
			if built.Marker.Project != wantDir {
				t.Fatalf("ratification built in %q; want %q", built.Marker.Project, wantDir)
			}
			if len(r.build.built) != 2 || !strings.HasSuffix(filepath.ToSlash(r.build.built[1]), "/"+wantDir) {
				t.Fatalf("builder did not receive the revised project directory: %v", r.build.built)
			}
			branch := built.Marker.Branch
			if oldDir == wantDir {
				if branch != oldBranch {
					t.Fatalf("same proposal and destination abandoned %q for %q", oldBranch, branch)
				}
			} else {
				if branch == oldBranch {
					t.Fatal("a different destination reused the earlier branch")
				}
				if head := git(t, r.origin, "rev-parse", oldBranch); head != oldHead {
					t.Fatalf("moving the project changed the old branch: %s -> %s", oldHead, head)
				}
				if files := git(t, r.origin, "ls-tree", "-r", "--name-only", branch, "--", oldDir); files != "" {
					t.Fatalf("fresh branch retained the abandoned project at %s:\n%s", oldDir, files)
				}
			}
			git(t, r.origin, "cat-file", "-e", branch+":"+wantDir+"/buffer/buffer.go")
			var lock project.Lock
			if err := json.Unmarshal([]byte(git(t, r.origin, "show", branch+":"+wantDir+"/.invariant/ratified.lock")), &lock); err != nil {
				t.Fatal(err)
			}
			if lock.Ratified == nil || lock.Ratified.Proposal != hash || lock.Ratified.Comment != ratify.URL ||
				project.ProposalHash(lock.Bounds, lock.Statements) != hash {
				t.Fatalf("new destination does not hold the person's unchanged ratified statements: %+v", lock)
			}
			if mod := git(t, r.origin, "show", branch+":"+wantDir+"/go.mod"); !strings.Contains(mod, "module github.com/o/r/"+wantDir+"\n") {
				t.Fatalf("project module still names an old destination: %s", mod)
			}
		})
	}
}

sources.internal/factory/shutdown_422_accept_tes:
package factory

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"os/signal"
	"path/filepath"
	"runtime"
	"strconv"
	"strings"
	"syscall"
	"testing"
	"time"

	"github.com/gitdek/invariant/internal/formalize"
	"github.com/gitdek/invariant/internal/synth"
)

type shutdown422Drain struct {
	started, canceled chan int
	allow             map[int]chan struct{}
}

func (d shutdown422Drain) Formalize(ctx context.Context, req formalize.Request, _ string) (*formalize.Result, error) {
	d.started <- req.Issue
	<-ctx.Done()
	d.canceled <- req.Issue
	<-d.allow[req.Issue]
	return nil, ctx.Err()
}

// Lease release is a barrier after every running step has finished. The
// replacement watcher uses the same clock, so waiting for expiration (or
// merely setting Until to now despite the skew window) cannot pass.
func TestCanceledWatcherReleasesLeaseAfterAllSteps422(t *testing.T) {
	for _, foreign := range []bool{false, true} {
		t.Run(fmt.Sprintf("foreign-replacement=%v", foreign), func(t *testing.T) {
			p := newParRig(t, 2)
			p.open(1)
			p.open(2)
			now := time.Date(2026, 11, 2, 12, 0, 0, 0, time.UTC)
			p.f.Holder, p.f.LeaseFor, p.f.Now = "stopping-422", 5*time.Minute, func() time.Time { return now }
			drain := shutdown422Drain{make(chan int, 2), make(chan int, 2), map[int]chan struct{}{1: make(chan struct{}), 2: make(chan struct{})}}
			p.f.Formalizer = drain
			ctx, cancel := context.WithCancel(context.Background())
			done := make(chan error, 1)
			go func() { done <- p.f.Watch(ctx, time.Hour) }()
			released := map[int]bool{}
			ended := false
			t.Cleanup(func() {
				cancel()
				for n, ch := range drain.allow {
					if !released[n] {
						close(ch)
					}
				}
				if !ended {
					select {
					case <-done:
					case <-time.After(10 * time.Second):
						t.Error("watcher did not finish fixture cleanup")
					}
				}
			})
			for range 2 {
				shutdown422Receive(t, drain.started, "a running step")
			}
			next := leaseFactory(t, p.origin, "successor-422", &now)
			cancel()
			for range 2 {
				shutdown422Receive(t, drain.canceled, "a step draining after cancellation")
			}
			if held, err := next.hold(context.Background()); err != nil || held {
				t.Fatalf("successor hold while canceled steps are draining = %v, %v", held, err)
			}
			close(drain.allow[1])
			released[1] = true
			if held, err := next.hold(context.Background()); err != nil || held {
				t.Fatalf("successor hold with another step still draining = %v, %v", held, err)
			}
			var replacement string
			if foreign {
				sha, _, err := next.Repo.Lease(context.Background())
				if err != nil {
					t.Fatal(err)
				}
				replacement, err = next.Repo.PushLease(context.Background(), sha, LeaseRecord{Holder: "another-422", Until: now.Add(time.Hour)})
				if err != nil {
					t.Fatal(err)
				}
			}
			close(drain.allow[2])
			released[2] = true
			select {
			case err := <-done:
				ended = true
				if err != nil && !errors.Is(err, context.Canceled) {
					t.Fatal(err)
				}
			case <-time.After(10 * time.Second):
				t.Fatal("watcher did not return once both steps stopped")
			}
			if foreign {
				sha, rec, err := next.Repo.Lease(context.Background())
				if err != nil || sha != replacement || rec.Holder != "another-422" {
					t.Fatalf("shutdown replaced another holder's lease: %s %+v %v", sha, rec, err)
				}
				return
			}
			if held, err := next.hold(context.Background()); err != nil || !held {
				t.Fatalf("all steps stopped, but a new watcher cannot immediately take the lease: held=%v, err=%v", held, err)
			}
		})
	}
}

func shutdown422Receive(t *testing.T, ch <-chan int, what string) int {
	t.Helper()
	select {
	case n := <-ch:
		return n
	case <-time.After(15 * time.Second):
		t.Fatalf("timed out waiting for %s", what)
		return 0
	}
}

type shutdown422Agent struct {
	backend synth.Backend
	work    string
}

func (a shutdown422Agent) Formalize(ctx context.Context, _ formalize.Request, _ string) (*formalize.Result, error) {
	_, err := a.backend.Run(ctx, synth.Job{Workspace: a.work, Prompt: "fixture", ReadOnly: true})
	return nil, err
}

// A real Watch and real agent backend run in a subprocess, with local Git
// and a stand-in CLI. SIGTERM reaches only the watcher, never its process
// group. The CLI's child and grandchild both inherit its output pipes, so
// killing only the CLI also leaves the step unable to finish reading.
func TestSIGTERMStopsAgentDescendantsAndReleasesLease422(t *testing.T) {
	if shutdown422Child(t) {
		return
	}
	for _, agent := range []string{"codex", "claude-code"} {
		t.Run(agent, func(t *testing.T) {
			origin, inspect := gitRepos(t)
			dir := t.TempDir()
			bin, err := os.Executable()
			if err != nil {
				t.Fatal(err)
			}
			quote := func(s string) string { return "'" + strings.ReplaceAll(s, "'", "'\"'\"'") + "'" }
			script := fmt.Sprintf("#!/bin/sh\nexec %s -test.run=^TestSIGTERMStopsAgentDescendantsAndReleasesLease422$ -- shutdown-422-fixture agent %s\n", quote(bin), quote(dir))
			if err := os.WriteFile(filepath.Join(dir, "agent"), []byte(script), 0o700); err != nil {
				t.Fatal(err)
			}
			log, err := os.Create(filepath.Join(dir, "watch.log"))
			if err != nil {
				t.Fatal(err)
			}
			defer log.Close()
			cmd := exec.Command(bin, "-test.run=^TestSIGTERMStopsAgentDescendantsAndReleasesLease422$", "--", "shutdown-422-fixture", "watch", dir, agent, origin)
			cmd.Env = append(os.Environ(), "GIT_CONFIG_GLOBAL=/dev/null", "GIT_CONFIG_SYSTEM=/dev/null")
			cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
			cmd.Stdout, cmd.Stderr = log, log
			if err := cmd.Start(); err != nil {
				t.Fatal(err)
			}
			done := make(chan error, 1)
			go func() { done <- cmd.Wait() }()
			ended := false
			pids := map[string]int{}
			t.Cleanup(func() {
				// Codex (and fixed ClaudeCode) owns a separate group. The
				// baseline ClaudeCode inherits the watcher's group. Clean both,
				// plus recorded descendants, on every exit path.
				for _, name := range []string{"agent", "child", "grandchild"} {
					if b, err := os.ReadFile(filepath.Join(dir, name+".pid")); err == nil {
						if pid, err := strconv.Atoi(strings.TrimSpace(string(b))); err == nil && pid > 1 {
							if name == "agent" {
								_ = syscall.Kill(-pid, syscall.SIGKILL)
							}
							_ = syscall.Kill(pid, syscall.SIGKILL)
						}
					}
				}
				_ = syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
				if !ended {
					select {
					case <-done:
					case <-time.After(5 * time.Second):
						t.Error("fixture watcher was not reaped after cleanup killed its group")
					}
				}
			})
			deadline := time.Now().Add(20 * time.Second)
			for len(pids) < 3 {
				for _, name := range []string{"agent", "child", "grandchild"} {
					if b, err := os.ReadFile(filepath.Join(dir, name+".pid")); err == nil {
						if pid, err := strconv.Atoi(strings.TrimSpace(string(b))); err == nil && pid > 1 {
							pids[name] = pid
						}
					}
				}
				select {
				case err := <-done:
					ended = true
					body, _ := os.ReadFile(filepath.Join(dir, "watch.log"))
					t.Fatalf("fixture watcher exited before its agent was ready: %v\n%s", err, body)
				default:
				}
				if time.Now().After(deadline) {
					body, _ := os.ReadFile(filepath.Join(dir, "watch.log"))
					t.Fatalf("fixture agent tree did not start: %v\n%s", pids, body)
				}
				time.Sleep(10 * time.Millisecond)
			}
			if sha, rec, err := inspect.Lease(context.Background()); err != nil || sha == "" || rec.Holder != "watcher-422" {
				t.Fatalf("running watcher did not hold a lease: %s %+v %v", sha, rec, err)
			}
			if err := cmd.Process.Signal(syscall.SIGTERM); err != nil {
				t.Fatal(err)
			}
			select {
			case err := <-done:
				ended = true
				if err != nil {
					body, _ := os.ReadFile(filepath.Join(dir, "watch.log"))
					t.Errorf("watcher failed to unwind after SIGTERM: %v\n%s", err, body)
				}
			case <-time.After(5 * time.Second):
				t.Error("watcher did not finish its canceled agent run after SIGTERM")
			}
			deadline = time.Now().Add(2 * time.Second)
			for name, pid := range pids {
				for shutdown422Alive(pid) && time.Now().Before(deadline) {
					time.Sleep(10 * time.Millisecond)
				}
				if shutdown422Alive(pid) {
					t.Errorf("%s process %d survived SIGTERM to its watcher", name, pid)
				}
			}
			now := time.Now()
			next := leaseFactory(t, origin, "next-422", &now)
			if held, err := next.hold(context.Background()); err != nil || !held {
				t.Errorf("SIGTERM left the watcher's lease unavailable to its successor: held=%v, err=%v", held, err)
			}
		})
	}
}

func shutdown422Alive(pid int) bool {
	if err := syscall.Kill(pid, 0); errors.Is(err, syscall.ESRCH) {
		return false
	}
	// A killed descendant may briefly remain an orphan zombie before init
	// reaps it. It cannot execute or spend anything and is not alive.
	if runtime.GOOS == "linux" {
		if out, err := os.ReadFile(fmt.Sprintf("/proc/%d/stat", pid)); err == nil {
			// The command name can contain spaces and parentheses; the state
			// is the first field after its final closing parenthesis.
			if at := strings.LastIndexByte(string(out), ')'); at >= 0 {
				fields := strings.Fields(string(out[at+1:]))
				if len(fields) > 0 && fields[0] == "Z" {
					return false
				}
			}
		}
	} else {
		ctx, cancel := context.WithTimeout(context.Background(), time.Second)
		defer cancel()
		out, err := exec.CommandContext(ctx, "ps", "-o", "stat=", "-p", strconv.Itoa(pid)).Output()
		if err == nil && strings.HasPrefix(strings.TrimSpace(string(out)), "Z") {
			return false
		}
	}
	// Failure to inspect the process is never evidence that it stopped.
	return !errors.Is(syscall.Kill(pid, 0), syscall.ESRCH)
}

